import {compile} from '../src/index.ts';
import {buildCompiledImports,wrapCompiledExports} from '../src/runtime.ts';
const cases={
 boolean:{source:'export function get():any{return function(...v:boolean[]):number{return v.length*1000+(v[v.length-1]?1:0);};}',args:Array(32).fill(true),expected:32001},
 string:{source:'export function get():any{return function(...v:string[]):number{return v.length*1000+v[v.length-1].length;};}',args:Array(32).fill('abc'),expected:32003},
 bigint:{source:'export function get():any{return function(...v:bigint[]):number{return v.length*1000+Number(v[v.length-1]);};}',args:Array(32).fill(42n),expected:32042},
 object:{source:'export function get():any{return function(...v:{n:number}[]):number{v[31].n=42;return v.length;};}',args:Array.from({length:32},()=>({n:1})),expected:32},
};
for(const[name,p]of Object.entries(cases)){try{const r=await compile(p.source,{skipSemanticDiagnostics:true});if(!r.success)throw Error(JSON.stringify(r.errors));const imports=buildCompiledImports(r);const{instance}=await WebAssembly.instantiate(r.binary,imports);imports.setInstance?.(instance);const ex=wrapCompiledExports(r,instance)as any;console.log(JSON.stringify({name,expected:p.expected,actual:ex.get()(...p.args),last:p.args[31]}));}catch(e:any){console.log(JSON.stringify({name,expected:p.expected,error:e?.message??String(e)}));}}
